return [{json:{
  project_id:'TATTOO_0002',
  reset_mode:'FULL_PIPELINE',
  reset_version:'SM3_TEST_FIXTURE_RESET_V1',
  confirmation_token:'RESET_TATTOO_0002_DERIVED_STATE',
  expected_confirmation_token:'RESET_TATTOO_0002_DERIVED_STATE',
  allowed_project_id:'TATTOO_0002',
  allowed_modes:['FULL_PIPELINE'],
  requested_at:new Date().toISOString()
}}];

const cfg = $('CONFIG — TEST FIXTURE').first().json;
const mediaRows = $('READ — FIXTURE MEDIA').all().map(i=>i.json);
const projectRows = $('READ — FIXTURE PROJECT').all().map(i=>i.json);
const contentRows = $('READ — FIXTURE CONTENT').all().map(i=>i.json);

const PROJECT_ID = String(cfg.project_id || '').trim();
const RESET_MODE = String(cfg.reset_mode || '').trim().toUpperCase();
const RESET_VERSION = String(cfg.reset_version || '').trim();
const now = new Date().toISOString();
const snapshotId = `SM3_TF_${Date.now()}`;

if (PROJECT_ID !== cfg.allowed_project_id) {
  throw new Error(`TEST_FIXTURE_BLOCK: project ${PROJECT_ID} is not allowed`);
}
if (!(cfg.allowed_modes || []).includes(RESET_MODE)) {
  throw new Error(`TEST_FIXTURE_BLOCK: mode ${RESET_MODE} is not allowed`);
}

const targetMedia = mediaRows.filter(r => String(r.ID_PROJETO || '').trim() === PROJECT_ID);
const targetProjects = projectRows.filter(r => String(r.ID_PROJETO || '').trim() === PROJECT_ID);
const targetContent = contentRows.filter(r => String(r.ID_PROJETO || '').trim() === PROJECT_ID);

if (targetMedia.length === 0) throw new Error('TEST_FIXTURE_BLOCK: no media for fixture project');
if (targetProjects.length !== 1) throw new Error(`TEST_FIXTURE_BLOCK: expected exactly 1 project row, found ${targetProjects.length}`);

const mediaDerivedFields = ["TRIAGEM", "QUALIDADE", "CONTEÚDO_VISUAL", "MELHOR_TRECHO", "USAR_EM", "ANALYSIS_STATUS", "ANALYSIS_VERSION", "ANALYSIS_SOURCE", "VISION_PROVIDER", "VISION_MODEL", "ANALYZED_AT", "ANALYSIS_ERROR", "EDITORIAL_SCORE", "PROXY_STATUS", "ANALYSIS_STAGE", "SHOT_TYPE", "TECHNICAL_NOTES", "TECHNICAL_SCORE", "COMPOSITION_SCORE", "TATTOO_VISIBILITY", "ANALYSIS_CONFIDENCE", "REDUNDANCY_HINT", "SCORE_SCALE_DETECTED", "SCORE_NORMALIZATION", "STRUCTURAL_ANALYSIS_VERSION", "GEOMETRY_MODE", "BODY_REGION", "BODY_SUBREGION", "VIEW_ANGLE", "BODY_POSE", "TATTOO_ORIENTATION", "TATTOO_STYLE_TAGS", "TATTOO_SUBJECT_PRIMARY", "TATTOO_SUBJECT_TAGS", "TATTOO_STAGE_STRUCTURAL", "TATTOO_COVERAGE", "COMPOSITION_SHAPE", "FOCAL_DESCRIPTION", "FOCUS_POINT_NORM", "TATTOO_BBOX_NORM", "CROP_GUIDANCE_JSON", "FORMAT_FIT_JSON", "BEST_FORMATS", "STRUCTURAL_CONFIDENCE", "STRUCTURAL_NOTES", "DATA_CAPTURA", "MIME_TYPE", "FILE_SIZE_BYTES", "CONTENT_HASH", "CAPTURED_AT_SOURCE", "TECHNICAL_METADATA_JSON", "PROCESS_STATUS", "RETRY_COUNT", "LAST_ATTEMPT_AT", "LAST_ERROR_CODE", "LAST_ERROR_MESSAGE", "LAST_FAILURE_STAGE", "LAST_FAILURE_NODE", "NEXT_RETRY_AT", "DEAD_LETTER_AT", "DEAD_LETTER_ID", "RELIABILITY_VERSION", "VIDEO_SAMPLING_MODE", "VIDEO_SAMPLING_VERSION", "SCENE_DETECTED_COUNT", "SELECTED_FRAME_COUNT", "SAMPLING_FALLBACK_USED", "SAMPLING_FALLBACK_REASON", "SAMPLING_DETAILS_JSON", "VIDEO_REANALYZED_AT", "CURATION_STATUS", "CURATION_VERSION", "CURATION_ROLE", "CURATION_RANK", "REDUNDANCY_GROUP", "REDUNDANCY_PREFERRED", "REDUNDANCY_REASON", "CAROUSEL_POSITION", "REEL_CANDIDATE", "CURATED_AT", "CURATION_PROVIDER", "CURATION_MODEL", "CURATION_CONFIDENCE", "CURATION_RUN_ID"];
const projectDerivedFields = ["CURATION_STATUS", "CURATION_VERSION", "CURATION_HERO_ID", "CURATION_SELECTED_IDS", "CURATION_RESERVE_IDS", "CURATION_DISCARD_IDS", "CURATION_CAROUSEL_ORDER", "CURATION_REEL_IDS", "CURATION_NARRATIVE", "CURATION_CONFIDENCE", "CURATED_AT", "CURATION_PROVIDER", "CURATION_MODEL", "CURATION_RUN_ID", "CONTENT_PLAN_STATUS", "CONTENT_PLAN_VERSION", "CONTENT_PLAN_RUN_ID", "CONTENT_PLAN_CURATED_FROM", "CONTENT_PLAN_AT", "CONTENT_PLAN_COUNT", "CONTENT_PLAN_PROVIDER", "CONTENT_PLAN_MODEL"];

function snapshot(entityType, entityId, sheet, row) {
  return {
    SNAPSHOT_ID:snapshotId,
    CREATED_AT:now,
    PROJECT_ID:PROJECT_ID,
    RESET_MODE:RESET_MODE,
    ENTITY_TYPE:entityType,
    ENTITY_ID:entityId,
    SOURCE_SHEET:sheet,
    SOURCE_ROW_NUMBER:String(row.row_number || ''),
    PAYLOAD_JSON:JSON.stringify(row),
    RESET_VERSION:RESET_VERSION,
    EXECUTION_ID:String($execution.id || ''),
    RESTORE_STATUS:'',
    RESTORED_AT:'',
    NOTES:'Snapshot automático antes do reset do lote canônico de regressão.'
  };
}

const snapshots = [];
for (const r of targetMedia) snapshots.push(snapshot('MEDIA', String(r.ID_MIDIA || ''), '03_MIDIAS', r));
for (const r of targetProjects) snapshots.push(snapshot('PROJECT', String(r.ID_PROJETO || ''), '01_PROJETOS', r));
for (const r of targetContent) snapshots.push(snapshot('CONTENT', String(r.ID_CONTEÚDO || ''), '04_CONTEUDOS', r));

const mediaUpdates = targetMedia.map(r => {
  const u = {ID_MIDIA:r.ID_MIDIA};
  for (const f of mediaDerivedFields) u[f] = '';

  // Canonical starting state for a complete regression pass.
  u.TRIAGEM = 'PENDENTE';
  u.ANALYSIS_STATUS = 'QUEUED';
  u.PROCESS_STATUS = 'READY';
  u.RETRY_COUNT = 0;
  u.RELIABILITY_VERSION = 'SM3_RELIABILITY_V1';

  return u;
});

const projectUpdates = targetProjects.map(r => {
  const u = {ID_PROJETO:r.ID_PROJETO};
  for (const f of projectDerivedFields) u[f] = '';
  return u;
});

const contentUpdates = targetContent.map(r => ({
  ID_CONTEÚDO:r.ID_CONTEÚDO,
  PLAN_STATUS:'TEST_ARCHIVED',
  STATUS_EDIÇÃO:'ARQUIVADO_TESTE',
  STATUS_APROVAÇÃO:'ARQUIVADO_TESTE',

  EDITORIAL_APPROVAL_STATUS:'TEST_ARCHIVED',
  EDITORIAL_COMMITTED_STATUS:'',
  EDITORIAL_APPROVAL_NOTES:'',
  EDITORIAL_DECIDED_AT:'',
  EDITORIAL_APPROVAL_VERSION:'SM3_EDITORIAL_GATE_V2',
  EDITORIAL_APPROVAL_SOURCE:'SM3_TEST_FIXTURE_RESET',

  FINAL_APPROVAL_STATUS:'TEST_ARCHIVED',
  FINAL_COMMITTED_STATUS:'',
  FINAL_APPROVAL_NOTES:'',
  FINAL_APPROVAL_DECIDED_AT:'',
  FINAL_APPROVAL_VERSION:'',
  FINAL_APPROVAL_SOURCE:'',

  ROUTING_STATUS:'TEST_ARCHIVED',
  ROUTING_VERSION:'SM3_ROUTING_V2_EDITORIAL',
  ROUTING_DECISION:'',
  ROUTING_TARGET:'ARCHIVE',
  ROUTED_AT:'',
  ROUTING_SOURCE:'SM3_TEST_FIXTURE_RESET',
  ROUTED_FROM_EDITORIAL_AT:'',

  PRODUCTION_STATUS:'NOT_APPLICABLE',
  REVISION_STATUS:'NOT_APPLICABLE',
  EDITORIAL_STATUS:'ARCHIVED_TEST',
  RENDER_STATUS:'NOT_APPLICABLE',
  RENDER_ID:'',
  RENDER_RECIPE_ID:'',
  QA_STATUS:'NOT_APPLICABLE',
  QA_NOTES:'',
  PIPELINE_STATE:'TEST_ARCHIVED',
  STATE_UPDATED_AT:now,
  STATE_VERSION:RESET_VERSION,
  FINAL_ARTIFACT_HASH:'',
  OBSERVAÇÕES:`${String(r.OBSERVAÇÕES || '').trim()}${String(r.OBSERVAÇÕES || '').trim() ? ' | ' : ''}[${RESET_VERSION} ${snapshotId}] Arquivado automaticamente para novo ciclo de regressão.`
}));

return [{
  json:{
    dry_run:false,
    project_id:PROJECT_ID,
    reset_mode:RESET_MODE,
    reset_version:RESET_VERSION,
    snapshot_id:snapshotId,
    media_count:targetMedia.length,
    project_count:targetProjects.length,
    content_count:targetContent.length,
    snapshots,
    media_updates:mediaUpdates,
    project_updates:projectUpdates,
    content_updates:contentUpdates,
    preservation_contract:{
      preserves:[
        'ID_MIDIA','ID_PROJETO','ARQUIVO','LINK_DRIVE','TIPO','SESSÃO',
        'DRIVE_FILE_ID','PROJECT_FOLDER_ID','PARENT_FOLDER_ID','RELATIVE_PATH',
        'INGESTION_KEY','STORAGE_STATUS','FIRST_SEEN_AT','LAST_SEEN_AT',
        'OFFLINE_AT','TREE_DEPTH','DISCOVERY_VERSION'
      ],
      archives_content_rows:true,
      deletes_rows:false
    },
    prepared_at:now
  }
}];
